import React, { useState, useEffect, useCallback } from 'react';
import SearchIcon from '@mui/icons-material/Search';
import { ArrowDropDown, Close as CloseIcon, Check as CheckIcon } from '@mui/icons-material';
import { debounce } from 'lodash';
import { useTheme } from '@mui/material/styles';
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Grid,
    Typography,
    CircularProgress,
    IconButton,
    Box,
    Avatar,
    Chip,
    Stack,
    TextField,
    InputAdornment,
    MenuItem,
    Select
} from '@mui/material';
import ApiRequest from 'utils/apiService';

export default function UnsplashGalleryDialog({ open, onClose, onSelect, selectedImages = [], onFinalSubmit, singleSelect = false }) {
    const theme = useTheme();
    const [images, setImages] = useState([]);
    const [page, setPage] = useState(1);
    const [loading, setLoading] = useState(false);
    const [hasMore, setHasMore] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [searchSource, setSearchSource] = useState('unsplash');
    const [isSearching, setIsSearching] = useState(false);
    const PER_PAGE = 10;

    const fetchImages = useCallback(async () => {
        if (!hasMore || loading) return;

        setLoading(true);
        try {
            const data = [
                {
                    id: 'img1',
                    alt: 'brown puppy playing in grass',
                    photographer: 'John Doe',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1586671267731-da2cf3ceeb80?w=400',
                        regular: 'https://images.unsplash.com/photo-1586671267731-da2cf3ceeb80?w=800',
                        thumb: 'https://images.unsplash.com/photo-1586671267731-da2cf3ceeb80?w=200'
                    }
                },
                {
                    id: 'img2',
                    alt: 'black cat on windowsill',
                    photographer: 'Jane Smith',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=400',
                        regular: 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800',
                        thumb: 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=200'
                    }
                },
                {
                    id: 'img3',
                    alt: 'golden retriever at beach',
                    photographer: 'Mike Johnson',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1633722715463-d30f4f325e24?w=400',
                        regular: 'https://images.unsplash.com/photo-1633722715463-d30f4f325e24?w=800',
                        thumb: 'https://images.unsplash.com/photo-1633722715463-d30f4f325e24?w=200'
                    }
                },
                {
                    id: 'img4',
                    alt: 'white rabbit in the snow',
                    photographer: 'Sarah Williams',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1556838803-cc94986cb631?w=400',
                        regular: 'https://images.unsplash.com/photo-1556838803-cc94986cb631?w=800',
                        thumb: 'https://images.unsplash.com/photo-1556838803-cc94986cb631?w=200'
                    }
                },
                {
                    id: 'img5',
                    alt: 'colorful parrot on a branch',
                    photographer: 'David Brown',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1552728089-57bdde30beb3?w=400',
                        regular: 'https://images.unsplash.com/photo-1552728089-57bdde30beb3?w=800',
                        thumb: 'https://images.unsplash.com/photo-1552728089-57bdde30beb3?w=200'
                    }
                },
                {
                    id: 'img6',
                    alt: 'squirrel eating a nut',
                    photographer: 'Lisa Taylor',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1566410824233-a8011929225c?w=400',
                        regular: 'https://images.unsplash.com/photo-1566410824233-a8011929225c?w=800',
                        thumb: 'https://images.unsplash.com/photo-1566410824233-a8011929225c?w=200'
                    }
                },
                {
                    id: 'img7',
                    alt: 'panda eating bamboo',
                    photographer: 'Robert Chen',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=400',
                        regular: 'https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=800',
                        thumb: 'https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=200'
                    }
                },
                {
                    id: 'img8',
                    alt: 'tiger resting in the shade',
                    photographer: 'Emma Wilson',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1562552476-8ac59b2a2e3a?w=400',
                        regular: 'https://images.unsplash.com/photo-1562552476-8ac59b2a2e3a?w=800',
                        thumb: 'https://images.unsplash.com/photo-1562552476-8ac59b2a2e3a?w=200'
                    }
                },
                {
                    id: 'img9',
                    alt: 'dolphin jumping out of water',
                    photographer: 'James Miller',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1545165375-48aa8e9e041b?w=400',
                        regular: 'https://images.unsplash.com/photo-1545165375-48aa8e9e041b?w=800',
                        thumb: 'https://images.unsplash.com/photo-1545165375-48aa8e9e041b?w=200'
                    }
                },
                {
                    id: 'img10',
                    alt: 'elephant spraying water',
                    photographer: 'Olivia Davis',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1557050543-4d5f4e07ef46?w=400',
                        regular: 'https://images.unsplash.com/photo-1557050543-4d5f4e07ef46?w=800',
                        thumb: 'https://images.unsplash.com/photo-1557050543-4d5f4e07ef46?w=200'
                    }
                },
                {
                    id: 'img11',
                    alt: 'koala sitting on a tree',
                    photographer: 'Nathan Green',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1504203700686-0be7f43f74a4?w=400',
                        regular: 'https://images.unsplash.com/photo-1504203700686-0be7f43f74a4?w=800',
                        thumb: 'https://images.unsplash.com/photo-1504203700686-0be7f43f74a4?w=200'
                    }
                },
                {
                    id: 'img12',
                    alt: 'flamingos standing in water',
                    photographer: 'Grace Lee',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1490717064594-3bd2edc1802e?w=400',
                        regular: 'https://images.unsplash.com/photo-1490717064594-3bd2edc1802e?w=800',
                        thumb: 'https://images.unsplash.com/photo-1490717064594-3bd2edc1802e?w=200'
                    }
                },
                {
                    id: 'img13',
                    alt: 'zebra grazing on field',
                    photographer: 'Kyle Martinez',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1560807707-8cc77767d783?w=400',
                        regular: 'https://images.unsplash.com/photo-1560807707-8cc77767d783?w=800',
                        thumb: 'https://images.unsplash.com/photo-1560807707-8cc77767d783?w=200'
                    }
                },
                {
                    id: 'img14',
                    alt: 'chimpanzee hanging from tree',
                    photographer: 'Nina Scott',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1584306671265-397b94a34e83?w=400',
                        regular: 'https://images.unsplash.com/photo-1584306671265-397b94a34e83?w=800',
                        thumb: 'https://images.unsplash.com/photo-1584306671265-397b94a34e83?w=200'
                    }
                },
                {
                    id: 'img15',
                    alt: 'penguins walking on ice',
                    photographer: 'Anthony White',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1602471943087-c2f0ba3cb7b6?w=400',
                        regular: 'https://images.unsplash.com/photo-1602471943087-c2f0ba3cb7b6?w=800',
                        thumb: 'https://images.unsplash.com/photo-1602471943087-c2f0ba3cb7b6?w=200'
                    }
                },
                {
                    id: 'img16',
                    alt: 'giraffe stretching neck to tree',
                    photographer: 'Laura Adams',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1504274066651-8d31a536b11a?w=400',
                        regular: 'https://images.unsplash.com/photo-1504274066651-8d31a536b11a?w=800',
                        thumb: 'https://images.unsplash.com/photo-1504274066651-8d31a536b11a?w=200'
                    }
                },
                {
                    id: 'img17',
                    alt: 'owl perched on wooden post',
                    photographer: 'Bryan Moore',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1556740738-b6a63e27c4df?w=400',
                        regular: 'https://images.unsplash.com/photo-1556740738-b6a63e27c4df?w=800',
                        thumb: 'https://images.unsplash.com/photo-1556740738-b6a63e27c4df?w=200'
                    }
                },
                {
                    id: 'img18',
                    alt: 'fox in a forest during autumn',
                    photographer: 'Isabella Turner',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1477332552946-cfb384aeaf1c?w=400',
                        regular: 'https://images.unsplash.com/photo-1477332552946-cfb384aeaf1c?w=800',
                        thumb: 'https://images.unsplash.com/photo-1477332552946-cfb384aeaf1c?w=200'
                    }
                },
                {
                    id: 'img19',
                    alt: 'wolf howling at night',
                    photographer: 'Samuel Hall',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1518173946687-a4c8893f3f5c?w=400',
                        regular: 'https://images.unsplash.com/photo-1518173946687-a4c8893f3f5c?w=800',
                        thumb: 'https://images.unsplash.com/photo-1518173946687-a4c8893f3f5c?w=200'
                    }
                },
                {
                    id: 'img20',
                    alt: 'peacock displaying feathers',
                    photographer: 'Ella Brooks',
                    urls: {
                        small: 'https://images.unsplash.com/photo-1508672019048-805c876b67e2?w=400',
                        regular: 'https://images.unsplash.com/photo-1508672019048-805c876b67e2?w=800',
                        thumb: 'https://images.unsplash.com/photo-1508672019048-805c876b67e2?w=200'
                    }
                }
            ];

            if (data?.length === 0) {
                setHasMore(false);
            } else {
                setImages((prev) => [...prev, ...data]);
                setPage((prev) => prev + 1);
            }
        } catch (error) {
            console.error('Error fetching images:', error);
        } finally {
            setLoading(false);
        }
    }, [page, hasMore, loading]);

    const handleScroll = useCallback(
        (e) => {
            const { scrollTop, clientHeight, scrollHeight } = e.currentTarget;
            if (scrollHeight - (scrollTop + clientHeight) < 100 && !loading && hasMore) {
                fetchImages();
            }
        },
        [fetchImages, loading, hasMore]
    );

    useEffect(() => {
        if (open) {
            setImages([]);
            setPage(1);
            setHasMore(true);
            fetchImages();
        }
    }, [open, fetchImages]);

    const isSelected = (image) => selectedImages.some((img) => img.id === image.id);

    const handleImageClick = (image) => {
        if (singleSelect) {
            onSelect(isSelected(image) ? [] : [image]);
            return;
        }

        // Multi select mode
        if (isSelected(image)) {
            onSelect(selectedImages.filter((img) => img.id !== image.id));
            return;
        }

        if (selectedImages.length < 6) {
            onSelect([...selectedImages, image]);
        }
    };

    const handleChipDelete = (image) => {
        onSelect(selectedImages.filter((img) => img.id !== image.id));
    };

    const handleFinalSubmit = () => {
        onFinalSubmit();
        onClose();
    };

    const handleSearch = useCallback(async () => {
        if (!searchQuery.trim()) return;

        setIsSearching(true);
        setImages([]);
        setPage(1);
        setHasMore(true);

        try {
            const response = await ApiRequest('GET', `unsplash/search?query=${searchQuery}&page=1&perPage=${PER_PAGE}`);
            setImages(response?.data || []);
            setHasMore(response?.data?.length === PER_PAGE);
        } catch (error) {
            console.error('Search error:', error);
        } finally {
            setIsSearching(false);
        }
    }, [searchQuery]);

    useEffect(() => {
        const timer = setTimeout(() => {
            if (searchQuery.trim()) {
                handleSearch();
            }
        }, 500);

        return () => clearTimeout(timer);
    }, [searchQuery, handleSearch]);

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="lg"
            fullWidth
            scroll="paper"
            PaperProps={{
                sx: {
                    backgroundColor: 'white'
                }
            }}
            aria-labelledby="unsplash-gallery-title"
        >
            <DialogTitle id="unsplash-gallery-title" style={{ background: theme.palette.text.primary }}>
                <Box display="flex" justifyContent="space-between" alignItems="center">
                    <Typography variant="h2">Search Media Online</Typography>
                    <IconButton onClick={onClose}>
                        <CloseIcon />
                    </IconButton>
                </Box>
                <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
                    <TextField
                        variant="outlined"
                        placeholder="Search for images..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        sx={{
                            width: '70%',
                            '& .MuiOutlinedInput-root': {
                                backgroundColor: theme.palette.text.primary,
                                '& fieldset': {
                                    border: `2px solid ${theme.palette.primary.main}`,
                                    borderRadius: '28px'
                                },
                                '&:hover fieldset': {
                                    border: `2px solid ${theme.palette.primary.main}`
                                }
                            }
                        }}
                        InputProps={{
                            endAdornment: (
                                <InputAdornment position="end">
                                    <Stack direction="row" spacing={2} alignItems="center">
                                        <Select
                                            value={searchSource}
                                            onChange={(e) => setSearchSource(e.target.value)}
                                            sx={{
                                                '& .MuiSelect-select': {
                                                    backgroundColor: theme.palette.text.primary,
                                                    color: 'black',
                                                    borderRadius: '0 !important',
                                                    padding: '1rem'
                                                },
                                                '& .MuiOutlinedInput-notchedOutline': {
                                                    borderLeft: '0.4px solid gray !important',
                                                    borderRadius: '0 !important',
                                                    borderRight: '0 !important'
                                                },
                                                '& .MuiSvgIcon-root': { color: 'black', right: '8px' },
                                                borderRadius: '0 !important'
                                            }}
                                            IconComponent={ArrowDropDown}
                                        >
                                            <MenuItem value="unsplash">Unsplash</MenuItem>
                                        </Select>
                                    </Stack>
                                </InputAdornment>
                            )
                        }}
                    />
                </Box>
            </DialogTitle>

            <DialogContent dividers onScroll={handleScroll} style={{ height: '100vh', background: theme.palette.text.primary }}>
                <Grid container spacing={2}>
                    {images?.map((image) => (
                        <Grid item xs={12} sm={6} md={3} key={image.id}>
                            <Box
                                position="relative"
                                onClick={() => handleImageClick(image)}
                                style={{
                                    cursor: 'pointer',
                                    border: isSelected(image) ? `3px solid ${theme.palette.primary.main}` : '3px solid transparent',
                                    borderRadius: 4,
                                    overflow: 'hidden',
                                    aspectRatio: '1/1'
                                }}
                            >
                                <img
                                    src={image?.urls?.small}
                                    alt={image?.alt_description || 'Unsplash image'}
                                    style={{
                                        width: '100%',
                                        height: '100%',
                                        objectFit: 'cover',
                                        display: 'block'
                                    }}
                                />
                                {isSelected(image) && (
                                    <Box
                                        sx={{
                                            position: 'absolute',
                                            top: 8,
                                            right: 8,
                                            backgroundColor: theme.palette.primary.main,
                                            borderRadius: '50%',
                                            width: 24,
                                            height: 24,
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center'
                                        }}
                                    >
                                        <CheckIcon sx={{ color: 'white', fontSize: 16 }} />
                                    </Box>
                                )}
                            </Box>
                        </Grid>
                    ))}
                </Grid>

                {loading && (
                    <Box display="flex" justifyContent="center" my={4}>
                        <CircularProgress />
                    </Box>
                )}

                {!hasMore && (
                    <Typography align="center" color="textSecondary" my={2}>
                        No more images to load
                    </Typography>
                )}
            </DialogContent>

            <DialogActions style={{ background: theme.palette.text.primary }}>
                <Stack direction="row" spacing={2} sx={{ width: '100%', justifyContent: 'space-between', px: 2 }}>
                    <Box
                        sx={{
                            display: 'flex',
                            gap: 1,
                            flexWrap: 'wrap',
                            maxWidth: '60%',
                            alignItems: 'center'
                        }}
                    >
                        {selectedImages.map((image) => (
                            <Chip
                                key={image.id}
                                avatar={<Avatar src={image?.urls?.thumb} alt={image?.alt_description} />}
                                label={image.alt_description?.substring(0, 15) + (image?.alt_description?.length > 15 ? '...' : '')}
                                onDelete={() => handleChipDelete(image)}
                                sx={{
                                    color: 'black',
                                    maxWidth: 200,
                                    '& .MuiChip-label': {
                                        overflow: 'hidden',
                                        textOverflow: 'ellipsis',
                                        whiteSpace: 'nowrap'
                                    }
                                }}
                            />
                        ))}
                    </Box>

                    <Stack direction="row" spacing={1}>
                        <Button onClick={onClose} color="secondary">
                            Cancel
                        </Button>
                        <Button onClick={handleFinalSubmit} variant="contained" color="success" disabled={selectedImages.length === 0}>
                            Done ({selectedImages.length}/6)
                        </Button>
                    </Stack>
                </Stack>
            </DialogActions>
        </Dialog>
    );
}
