import React, { useState, useCallback } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    TextField,
    Button,
    Grid,
    Box,
    CircularProgress,
    Typography,
    IconButton,
    Avatar,
    Chip,
    Stack
} from '@mui/material';
import { Close as CloseIcon, Check as CheckIcon } from '@mui/icons-material';
import { useTheme } from '@mui/material/styles';
import ApiRequest from 'utils/apiService';

export default function DeepSeekDialog({ open, onClose, onSelect, selectedImages = [], onFinalSubmit, singleSelect = true }) {
    const theme = useTheme();
    const [prompt, setPrompt] = useState('');
    const [generatedImages, setGeneratedImages] = useState([]);
    const [isGenerating, setIsGenerating] = useState(false);
    const [error, setError] = useState(null);

    const handleGenerate = useCallback(async () => {
        if (!prompt.trim()) return;

        setIsGenerating(true);
        setError(null);

        try {
            // Replace with actual DeepSeek API call
            const response = await ApiRequest('POST', 'deep-seek/generate-image', {
                prompt,
                size: '1024x1024',
                n: 2
            });

            const formattedImages = (response.data || []).map((img) => ({
                ...img,
                id: `ai-img-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
            }));

            setGeneratedImages(formattedImages);
        } catch (err) {
            setError('Failed to generate images. Please try again.');
            console.error(err);
        } finally {
            setIsGenerating(false);
        }
    }, [prompt]);

    const handleImageClick = (image) => {
        if (singleSelect) {
            // For single select mode - replace current selection
            onSelect([image]);
        } else {
            // For multi-select mode - toggle selection
            const isSelected = selectedImages.some((img) => img.id === image.id);
            if (isSelected) {
                onSelect(selectedImages.filter((img) => img.id !== image.id));
            } else if (selectedImages.length < 6) {
                onSelect([...selectedImages, image]);
            }
        }
    };

    const handleChipDelete = (image) => {
        onSelect(selectedImages.filter((img) => img.id !== image.id));
    };

    const handleFinalSubmit = () => {
        onFinalSubmit();
        onClose();
    };

    const isSelected = (image) => selectedImages.some((img) => img?.id === image?.id);

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="lg"
            fullWidth
            PaperProps={{
                sx: { backgroundColor: 'white' }
            }}
        >
            <DialogTitle sx={{ background: theme.palette.text.primary }}>
                <Box display="flex" justifyContent="space-between" alignItems="center">
                    <Typography variant="h2">AI Image Generator</Typography>
                    <IconButton onClick={onClose}>
                        <CloseIcon />
                    </IconButton>
                </Box>
            </DialogTitle>

            <DialogContent dividers sx={{ background: theme.palette.text.primary }}>
                <Box sx={{ mb: 3 }}>
                    <TextField
                        fullWidth
                        variant="outlined"
                        placeholder="Describe the image you want to create..."
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                backgroundColor: theme.palette.text.primary,
                                '& fieldset': {
                                    border: `2px solid ${theme.palette.primary.main}`,
                                    borderRadius: '28px'
                                }
                            }
                        }}
                        InputProps={{
                            endAdornment: (
                                <Button
                                    variant="contained"
                                    onClick={handleGenerate}
                                    disabled={isGenerating || !prompt.trim()}
                                    sx={{
                                        borderRadius: '28px',
                                        backgroundColor: `${theme.palette.primary.main} !important`,
                                        '&:hover': {
                                            backgroundColor: `${theme.palette.primary.dark} !important`
                                        }
                                    }}
                                >
                                    {isGenerating ? <CircularProgress size={24} color="inherit" /> : 'Generate'}
                                </Button>
                            )
                        }}
                    />
                </Box>

                {error && (
                    <Typography color="error" sx={{ mb: 2 }}>
                        {error}
                    </Typography>
                )}

                <Grid container spacing={2}>
                    {generatedImages.map((image) => (
                        <Grid item xs={12} sm={6} md={3} key={image?.id}>
                            <Box
                                position="relative"
                                onClick={() => handleImageClick(image)}
                                sx={{
                                    cursor: 'pointer',
                                    border: isSelected(image) ? `3px solid ${theme.palette.primary.main}` : '3px solid transparent',
                                    borderRadius: 1,
                                    overflow: 'hidden',
                                    aspectRatio: '1/1'
                                }}
                            >
                                <img
                                    src={image?.url}
                                    alt={image?.prompt || 'AI-generated content'}
                                    style={{
                                        width: '100%',
                                        height: '100%',
                                        objectFit: 'cover'
                                    }}
                                />
                                {isSelected(image) && (
                                    <Box
                                        sx={{
                                            position: 'absolute',
                                            top: 8,
                                            right: 8,
                                            backgroundColor: theme.palette.primary.main,
                                            borderRadius: '50%',
                                            width: 24,
                                            height: 24,
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center'
                                        }}
                                    >
                                        <CheckIcon sx={{ color: 'white', fontSize: 16 }} />
                                    </Box>
                                )}
                            </Box>
                        </Grid>
                    ))}
                </Grid>
            </DialogContent>

            <DialogActions sx={{ background: theme.palette.text.primary }}>
                <Stack direction="row" spacing={2} sx={{ width: '100%', justifyContent: 'space-between', px: 2 }}>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', maxWidth: '60%' }}>
                        {selectedImages.map((image) => (
                            <Chip
                                key={image?.id}
                                avatar={<Avatar src={image?.url} alt={image?.prompt} />}
                                label={`${image?.prompt?.substring(0, 15)}...`}
                                onDelete={() => handleChipDelete(image)}
                                sx={{
                                    color: 'black',
                                    maxWidth: 200,
                                    '& .MuiChip-label': {
                                        overflow: 'hidden',
                                        textOverflow: 'ellipsis',
                                        whiteSpace: 'nowrap'
                                    }
                                }}
                            />
                        ))}
                    </Box>
                    <Stack direction="row" spacing={1}>
                        <Button onClick={onClose} color="secondary">
                            Cancel
                        </Button>
                        <Button onClick={handleFinalSubmit} variant="contained" color="success" disabled={selectedImages.length === 0}>
                            {singleSelect ? 'Select' : `Done (${selectedImages.length}/6)`}
                        </Button>
                    </Stack>
                </Stack>
            </DialogActions>
        </Dialog>
    );
}
